 17→// BenchmarkHookSessionStart measures the end-to-end latency of the
 18→// "entire hooks claude-code session-start" subprocess.
 19→//
 20→// Each sub-benchmark isolates a single scaling dimension that appears
 21→// in the session-start hot path (see hook_registry.go → lifecycle.go):
 22→//
 23→//   - Sessions:      store.List() called 2x, ReadDir + ReadFile + unmarshal + repo.Reference() per file
 24→//   - SessionsXRefs: sessions × refs interaction (repo.Reference scans packed-refs per session)
 25→//   - PackedRefs:    go-git PlainOpen + repo.Reference cost with many packed refs
 26→//   - GitObjects:    go-git PlainOpen cost with large .git/objects packfile
 27→//   - Subprocess:    isolates git rev-parse and binary spawn overhead
 28→//
 29→// Run all:
 30→//
 31→//	go test -tags=integration -bench=BenchmarkHookSessionStart -benchtime=3x -run='^$' -timeout=10m ./cmd/entire/cli/integration_test/...
 32→//
 33→// Run one dimension:
 34→//
 35→//	go test -tags=integration -bench=BenchmarkHookSessionStart/Subprocess -benchtime=5x -run='^$' ./cmd/entire/cli/integration_test/...
 36→func BenchmarkHookSessionStart(b *testing.B) {
 37→	b.Run("Sessions", benchSessions)
 38→	b.Run("SessionsXRefs", benchSessionsXRefs)
 39→	b.Run("PackedRefs", benchPackedRefs)
 40→	b.Run("GitObjects", benchGitObjects)
 41→	b.Run("Subprocess", benchSubprocessOverhead)
 42→}
