 44→// benchSessions scales session state files in .git/entire-sessions/.
 45→// listAllSessionStates() is called twice: once in FindMostRecentSession (logging init),
 46→// once in CountOtherActiveSessionsWithCheckpoints. Each call does
 47→// ReadDir + (ReadFile + JSON unmarshal + repo.Reference) per file.
 48→func benchSessions(b *testing.B) {
 49→	for _, n := range []int{0, 1, 5, 10, 25, 50, 100, 200} {
 50→		b.Run(fmt.Sprintf("%d", n), func(b *testing.B) {
 51→			repo := benchutil.NewBenchRepo(b, benchutil.RepoOpts{
 52→				FileCount:     10,
 53→				FeatureBranch: "feature/bench",
 54→			})
 55→			for range n {
 56→				repo.CreateSessionState(b, benchutil.SessionOpts{
 57→					StepCount:    3,
 58→					FilesTouched: []string{"src/file_000.go", "src/file_001.go"},
 59→				})
 60→			}
 61→			runSessionStartHook(b, repo)
 62→		})
 63→	}
 64→}
